import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced/Performance.md","filePath":"guide/advanced/Performance.md"}`),a={name:`guide/advanced/Performance.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to “性能优化”">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>文字游戏的性能问题，通常不会表现为“掉帧”，而是<strong>每次输入后要等一两秒才响应</strong>。这一篇讲讲卡顿从哪来、怎么找、怎么改。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已完成<a href="./../tutorials/">入门教程</a>与<a href="./Case_Study.html">完整实战：打工养成</a>。</p></div><h2 id="先测量-再优化" tabindex="-1">先测量，再优化 <a class="header-anchor" href="#先测量-再优化" aria-label="Permalink to “先测量，再优化”">​</a></h2><p>不要凭感觉猜。Emuera 提供了计时函数：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> T0</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> T1</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#9CDCFE;">GETMILLISECOND</span></span>
<span class="line"><span style="color:#9CDCFE;">T0</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> RESULT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">; ……要测量的处理……</span></span>
<span class="line"></span>
<span class="line"><span style="color:#9CDCFE;">GETMILLISECOND</span></span>
<span class="line"><span style="color:#9CDCFE;">T1</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> RESULT</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> 耗时 </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">T1</span><span style="color:#D4D4D4;"> - </span><span style="color:#9CDCFE;">T0</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;"> 毫秒</span></span></code></pre></div><p>先量出<strong>到底是哪一段慢</strong>，再动手。大多数时候，瓶颈都集中在少数几个地方。</p><h2 id="瓶颈一-循环" tabindex="-1">瓶颈一：循环 <a class="header-anchor" href="#瓶颈一-循环" aria-label="Permalink to “瓶颈一：循环”">​</a></h2><p>这是最常见的性能来源。几条经验：</p><h3 id="用内置命令代替手写循环" tabindex="-1">用内置命令代替手写循环 <a class="header-anchor" href="#用内置命令代替手写循环" aria-label="Permalink to “用内置命令代替手写循环”">​</a></h3><p>同样的“批量操作”，内置命令通常快得多：</p><table tabindex="0"><thead><tr><th>需求</th><th>手写循环</th><th>推荐</th></tr></thead><tbody><tr><td>给数组批量赋值</td><td><code>FOR</code> 逐个赋值</td><td><code>VARSET</code> / <code>CVARSET</code></td></tr><tr><td>排序</td><td>自己实现冒泡 / 快排</td><td><code>ARRAYSORT</code></td></tr><tr><td>复制数组</td><td><code>FOR</code> 逐个复制</td><td><code>ARRAYCOPY</code></td></tr><tr><td>平移 / 删除元素</td><td><code>FOR</code> 手动挪动</td><td><code>ARRAYSHIFT</code> / <code>ARRAYREMOVE</code></td></tr></tbody></table><p>例如给 <code>FLAG</code> 全部清零，写 <code>VARSET FLAG, 0</code> 远比 <code>FOR … NEXT</code> 快。</p><h3 id="减少循环内的重复计算" tabindex="-1">减少循环内的重复计算 <a class="header-anchor" href="#减少循环内的重复计算" aria-label="Permalink to “减少循环内的重复计算”">​</a></h3><p>把不变的东西挪到循环外面：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">; 不好：每次循环都重复求 VARSIZE</span></span>
<span class="line"><span style="color:#C586C0;">FOR</span><span style="color:#9CDCFE;"> I</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#DCDCAA;">VARSIZE</span><span style="color:#E6E6E6;">(</span><span style="color:#CE9178;">&quot;FLAG&quot;</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#E6E6E6;">  ...</span></span>
<span class="line"><span style="color:#C586C0;">NEXT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">; 更好：只在循环外求一次</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> N</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#9CDCFE;">N</span><span style="color:#D4D4D4;"> =</span><span style="color:#DCDCAA;"> VARSIZE</span><span style="color:#E6E6E6;">(</span><span style="color:#CE9178;">&quot;FLAG&quot;</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#C586C0;">FOR</span><span style="color:#9CDCFE;"> I</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">N</span></span>
<span class="line"><span style="color:#E6E6E6;">  ...</span></span>
<span class="line"><span style="color:#C586C0;">NEXT</span></span></code></pre></div><h3 id="尽量早退出" tabindex="-1">尽量早退出 <a class="header-anchor" href="#尽量早退出" aria-label="Permalink to “尽量早退出”">​</a></h3><p>找到结果就用 <code>BREAK</code> / <code>RETURN</code> 结束，别把整个数组都遍历完。</p><h2 id="瓶颈二-字符串" tabindex="-1">瓶颈二：字符串 <a class="header-anchor" href="#瓶颈二-字符串" aria-label="Permalink to “瓶颈二：字符串”">​</a></h2><ul><li>少在循环里做大量的 <code>+</code> 拼接，累积成一段再一次性输出；</li><li>避免在循环里反复调用 <code>STRLEN</code> / <code>STRLENS</code> 等度量函数，能提前算好就提前算；</li><li>需要重复显示同一段内容时，缓存到字符串变量里。</li></ul><h2 id="瓶颈三-绘制" tabindex="-1">瓶颈三：绘制 <a class="header-anchor" href="#瓶颈三-绘制" aria-label="Permalink to “瓶颈三：绘制”">​</a></h2><ul><li><code>フレーム毎秒</code>（每秒帧数）越小，绘制越省；牺牲一点动画流畅度换取响应速度，往往是值得的；</li><li>不需要每帧更新时，用 <code>REDRAW 0</code> 暂停自动重绘，只在需要输入时刷新；</li><li>避免在循环里反复 <code>CLEARLINE</code> + 重绘整屏。</li></ul><h2 id="耗时任务-分批-await" tabindex="-1">耗时任务：分批 + AWAIT <a class="header-anchor" href="#耗时任务-分批-await" aria-label="Permalink to “耗时任务：分批 + AWAIT”">​</a></h2><p>如果某一步确实要算很久（例如初始化大量数据），不要让它“卡死”界面。可以边算边显示进度：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">REDRAW</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#C586C0;">FOR</span><span style="color:#9CDCFE;"> I</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">100</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTSL</span><span style="color:#CE9178;"> &quot;处理中…… &quot;</span><span style="color:#D4D4D4;"> +</span><span style="color:#DCDCAA;"> TOSTR</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">I</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">+</span><span style="color:#CE9178;"> &quot;％ 完成&quot;</span></span>
<span class="line"><span style="color:#569CD6;">  AWAIT</span></span>
<span class="line"><span style="color:#569CD6;">  CLEARLINE</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#6A9955;">  ; 这一批的处理</span></span>
<span class="line"><span style="color:#C586C0;">NEXT</span></span></code></pre></div><p><code>AWAIT</code> 会暂停 ERB 执行、让 Windows 处理消息，避免窗口“无响应”。但也不要调用得过于频繁，否则反而变慢。</p><h2 id="一个反直觉的建议" tabindex="-1">一个反直觉的建议 <a class="header-anchor" href="#一个反直觉的建议" aria-label="Permalink to “一个反直觉的建议”">​</a></h2><p><strong>可读性优先于微优化。</strong></p><p>绝大多数文字游戏，经过上面的调整后性能都绰绰有余。为了省几毫秒把代码写得晦涩难懂，通常是得不偿失的——真正需要死抠性能的场景，其实很少。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li>先用 <code>GETMILLISECOND</code> 测量，再优化；</li><li>循环是主要瓶颈：优先用内置的批量命令；</li><li>把循环内不变的计算挪出去，尽早 <code>BREAK</code> / <code>RETURN</code>；</li><li>减少字符串拼接与重复度量；</li><li>用 <code>REDRAW</code>、<code>フレーム毎秒</code> 控制绘制开销；</li><li>耗时任务分批处理并配合 <code>AWAIT</code>。</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./Experience.html">开发实战经验与技巧</a></li><li><a href="./../../translation/Command.html">命令</a></li><li><a href="./../../translation/Config_Settings.html">配置项详解</a></li></ul>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};